<?php use App\Support\View; ?>
<main class="content report-page"><header class="topbar"><div><span class="eyebrow">Súmula digital</span><h1><?=View::e($match['home_name'])?> <?=$match['home_score']?> × <?=$match['away_score']?> <?=View::e($match['away_name'])?></h1><p class="muted"><?=View::e($match['tournament_name'])?> · <?=View::e($match['stage_name']??'')?> · <?=View::e($match['round_name']??'')?></p></div><a class="button" href="/admin/tournaments/<?=$match['tournament_id']?>/operation">Voltar à operação</a></header><section class="panel"><h2>Dados da partida</h2><dl class="report-meta"><div><dt>Data</dt><dd><?=View::e($match['scheduled_at']??'A definir')?></dd></div><div><dt>Grupo</dt><dd><?=View::e($match['group_name']??'—')?></dd></div><div><dt>Status</dt><dd><?=View::e($match['status'])?></dd></div><div><dt>Versão</dt><dd><?=View::e($match['report_version']??'1')?></dd></div></dl></section><section class="panel"><h2>Escalações</h2><div class="table-wrap"><table><thead><tr><th>Equipe</th><th>Atleta</th><th>Função</th><th>Número</th><th>Capitão</th><th>Goleiro</th></tr></thead><tbody><?php foreach($lineups as $lineup):?><tr><td><?=View::e($lineup['team_name'])?></td><td><?=View::e($lineup['full_name'])?></td><td><?=View::e($lineup['lineup_role'])?></td><td><?=View::e($lineup['shirt_number'])?></td><td><?=$lineup['is_captain']?'Sim':'Não'?></td><td><?=$lineup['is_goalkeeper']?'Sim':'Não'?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><h2>Cronologia</h2><div class="table-wrap"><table><thead><tr><th>Minuto</th><th>Período</th><th>Evento</th><th>Equipe</th><th>Atleta</th></tr></thead><tbody><?php foreach($events as $event):?><tr><td><?=View::e($event['minute']??'—')?></td><td><?=View::e($event['period']??'—')?></td><td><?=View::e($event['event_type'])?><?=$event['is_cancelled']?' (anulado)':''?></td><td><?=View::e($event['team_name']??'—')?></td><td><?=View::e($event['full_name']??'—')?></td></tr><?php endforeach;?></tbody></table></div></section></main>
